diff --git a/src/sanitize-svg.js b/src/sanitize-svg.js
new file mode 100644
index 0000000..9a51e06
--- /dev/null
+++ b/src/sanitize-svg.js
@@ -0,0 +1,65 @@
+'use strict';
+
+const blockedElements = {
+    animate: true,
+    animatemotion: true,
+    animatetransform: true,
+    discard: true,
+    embed: true,
+    foreignobject: true,
+    iframe: true,
+    object: true,
+    script: true,
+    set: true
+};
+
+const uriAttributes = {
+    action: true,
+    formaction: true,
+    href: true,
+    src: true
+};
+
+const isUnsafeUri = function (value) {
+    const normalized = value.replace(/[\u0000-\u0020]/g, '').toLowerCase();
+    if (/^(?:javascript|vbscript):/.test(normalized)) {
+        return true;
+    }
+
+    return normalized.indexOf('data:') === 0 &&
+        !/^data:image\/(?:gif|jpe?g|png|webp);base64,/.test(normalized);
+};
+
+const sanitizeElement = function (element) {
+    for (let i = element.attributes.length - 1; i >= 0; i--) {
+        const attribute = element.attributes[i];
+        const name = attribute.localName.toLowerCase();
+        const value = attribute.value;
+
+        if (name.indexOf('on') === 0 ||
+            name === 'srcdoc' ||
+            (uriAttributes[name] && isUnsafeUri(value)) ||
+            (name === 'style' && /(?:javascript|vbscript)\s*:/i.test(value))) {
+            element.removeAttribute(attribute.name);
+        }
+    }
+
+    const children = Array.prototype.slice.call(element.childNodes);
+    children.forEach(child => {
+        if (child.nodeType !== 1) {
+            return;
+        }
+
+        const name = child.localName.toLowerCase();
+        if (blockedElements[name]) {
+            element.removeChild(child);
+        } else {
+            sanitizeElement(child);
+        }
+    });
+};
+
+module.exports = function (svgTag) {
+    sanitizeElement(svgTag);
+    return svgTag;
+};

