+impl QeIdentity {
+    pub(crate) fn verify_report(&self, report: &ReportBody) -> Result<()> {
+        let miscselect = decode_array::<4>(&self.miscselect)?;
+        let miscselect_mask = decode_array::<4>(&self.miscselect_mask)?;
+        if !masked_eq(&report.misc_select, &miscselect, &miscselect_mask) {
+            return Err(Error::QeIdentityMismatch);
+        }
+
+        let attributes = decode_array::<16>(&self.attributes)?;
+        let attributes_mask = decode_array::<16>(&self.attributes_mask)?;
+        if !masked_eq(&report.attributes, &attributes, &attributes_mask) {
+            return Err(Error::QeIdentityMismatch);
+        }
+
+        let mrsigner = decode_array::<32>(&self.mrsigner)?;
+        if report.mr_signer != mrsigner || report.isv_prod_id != self.isvprodid {
+            return Err(Error::QeIdentityMismatch);
+        }
+
+        // TCB levels are ordered from newest to oldest by PCS.  A report must
+        // satisfy at least one level; otherwise its ISVSVN predates every
+        // approved QE TCB level.
+        if !self
+            .tcb_levels
+            .iter()
+            .any(|level| report.isv_svn >= level.tcb.isvsvn)
+        {
+            return Err(Error::QeIdentityMismatch);
+        }
+
+        Ok(())
+    }
+}
+
+fn decode_array<const N: usize>(value: &str) -> Result<[u8; N]> {
+    let bytes = hex::decode(value).map_err(|_| Error::InvalidQeIdentity)?;
+    bytes
+        .try_into()
+        .map_err(|_| Error::InvalidQeIdentity)
+}
+
+fn masked_eq<const N: usize>(actual: &[u8; N], expected: &[u8; N], mask: &[u8; N]) -> bool {
+    actual
+        .iter()
+        .zip(expected)
+        .zip(mask)
+        .all(|((&actual, &expected), &mask)| (actual & mask) == (expected & mask))
+}
